import { ok, fail } from './result.js';
import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Validate discountPercent is a number between 0 and 100.
 * @param {any} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate the due date based on terms and issue date.
 * @param {string} issueDate in YYYY-MM-DD format
 * @param {string} terms NET14, NET30, or EOM
 * @returns {string} due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  }
  if (terms === 'NET30') {
    return addDays(issueDate, 30);
  }
  if (terms === 'EOM') {
    // Get the last day of the month by going to first day of next month and back 1 day
    const [year, month, day] = issueDate.split('-').map(Number);
    const nextMonth = month === 12 ? `${year + 1}-01-01` : `${year}-${String(month + 1).padStart(2, '0')}-01`;
    return addDays(nextMonth, -1);
  }
  return null;
}

/**
 * Create an invoice from customer id, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} input
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and set terms (default to NET30)
  const finalTerms = terms ?? 'NET30';
  if (!['NET14', 'NET30', 'EOM'].includes(finalTerms)) return fail('TERMS_INVALID');

  // Validate lines is not empty
  if (!lines || !Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Get tier discount for this customer
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  // Enrich and validate lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    // Use explicit discountPercent if provided, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;

    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const dueDate = calculateDueDate(issueDate, finalTerms);

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    terms: finalTerms,
    dueDate,
    status: 'draft',
    lines: enrichedLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total amount for a line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a line (lineTotal × discountPercent / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} discount in cents
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  return roundCents(total * discountPercent / 100);
}

/**
 * Calculate the VAT amount for a line ((lineTotal - lineDiscount) × vatRate / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = total - discount;
  const vatRate = line.vatRate ?? 0;
  return roundCents(amountAfterDiscount * vatRate / 100);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} all in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: { code: string, amount: number }, lines: Array<any> }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check if status is 'draft'
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  // Check if voucher already exists
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Create new invoice with voucher applied
  const newInvoice = {
    ...invoice,
    voucher: { code, amount },
  };

  return ok(newInvoice);
}

/**
 * Add a line to an invoice. If the SKU already exists, increase its qty.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check if status is 'draft'
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent if provided
  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate and get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Get customer to access tier discount if needed
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if line with this SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    newLines[existingLineIndex].qty += qty;
    if (discountPercent !== undefined) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    }
  } else {
    // Use explicit discountPercent if provided, otherwise use tier discount
    const lineDiscountPercent = discountPercent !== undefined ? discountPercent : tierDiscount;
    newLines.push({
      sku: sku,
      name: product.name,
      qty: qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: lineDiscountPercent,
    });
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check if status is 'draft'
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if line with this SKU exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if removing this line would result in no lines
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without the line at lineIndex
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue a draft invoice by assigning a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers - array of invoice numbers already used
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check if status is 'draft'
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(newInvoice);
}

